CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_status AS ENUM ('pending','approved','rejected','blocked'); CREATE TYPE user_role AS ENUM ('user','moderator','admin'); CREATE TYPE friendship_status AS ENUM ('pending','accepted','blocked'); CREATE TYPE group_visibility AS ENUM ('public','private'); CREATE TYPE group_member_role AS ENUM ('member','moderator','owner');
CREATE TABLE users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),username VARCHAR(24) NOT NULL UNIQUE,email VARCHAR(160) NOT NULL UNIQUE,password_hash TEXT NOT NULL,role user_role NOT NULL DEFAULT 'user',status user_status NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE TABLE profiles(user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,display_name VARCHAR(60) NOT NULL,avatar_url TEXT,bio VARCHAR(500),score INT NOT NULL DEFAULT 0,level INT NOT NULL DEFAULT 1,updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE TABLE user_favorite_games(user_id UUID REFERENCES users(id) ON DELETE CASCADE,game_name VARCHAR(80) NOT NULL,PRIMARY KEY(user_id,game_name)); CREATE TABLE follows(follower_id UUID REFERENCES users(id) ON DELETE CASCADE,following_id UUID REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(follower_id,following_id),CHECK(follower_id<>following_id)); CREATE TABLE friendships(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),requester_id UUID REFERENCES users(id) ON DELETE CASCADE,addressee_id UUID REFERENCES users(id) ON DELETE CASCADE,status friendship_status NOT NULL DEFAULT 'pending',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(requester_id,addressee_id),CHECK(requester_id<>addressee_id)); CREATE TABLE news(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),author_id UUID REFERENCES users(id) ON DELETE SET NULL,title VARCHAR(180) NOT NULL,excerpt VARCHAR(400),body TEXT NOT NULL,category VARCHAR(30) NOT NULL CHECK(category IN('Gaming','Esports','Hardware','Updates')),cover_url TEXT,published BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE TABLE news_likes(news_id UUID REFERENCES news(id) ON DELETE CASCADE,user_id UUID REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(news_id,user_id)); CREATE TABLE comments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),author_id UUID REFERENCES users(id) ON DELETE SET NULL,news_id UUID REFERENCES news(id) ON DELETE CASCADE,body VARCHAR(1000) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE TABLE comment_likes(comment_id UUID REFERENCES comments(id) ON DELETE CASCADE,user_id UUID REFERENCES users(id) ON DELETE CASCADE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(comment_id,user_id)); CREATE TABLE groups(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),owner_id UUID REFERENCES users(id) ON DELETE SET NULL,name VARCHAR(80) NOT NULL,description VARCHAR(500),avatar_url TEXT,visibility group_visibility NOT NULL DEFAULT 'public',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE TABLE group_members(group_id UUID REFERENCES groups(id) ON DELETE CASCADE,user_id UUID REFERENCES users(id) ON DELETE CASCADE,role group_member_role NOT NULL DEFAULT 'member',approved BOOLEAN NOT NULL DEFAULT TRUE,joined_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),PRIMARY KEY(group_id,user_id)); CREATE TABLE notifications(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users(id) ON DELETE CASCADE,type VARCHAR(40) NOT NULL,title VARCHAR(140) NOT NULL,body VARCHAR(500),read_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()); CREATE TABLE reports(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),reporter_id UUID REFERENCES users(id) ON DELETE SET NULL,target_type VARCHAR(30) NOT NULL,target_id UUID NOT NULL,reason VARCHAR(500) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),resolved_at TIMESTAMPTZ);
CREATE INDEX idx_users_status ON users(status); CREATE INDEX idx_profiles_score ON profiles(score DESC); CREATE INDEX idx_follows_following ON follows(following_id); CREATE INDEX idx_news_category_created ON news(category,created_at DESC); CREATE INDEX idx_news_published_created ON news(published,created_at DESC); CREATE INDEX idx_comments_news_created ON comments(news_id,created_at DESC); CREATE INDEX idx_groups_visibility_created ON groups(visibility,created_at DESC); CREATE INDEX idx_group_members_user ON group_members(user_id); CREATE INDEX idx_notifications_user_created ON notifications(user_id,created_at DESC); CREATE INDEX idx_reports_status_created ON reports(status,created_at DESC);